create table if not exists public.orders(id uuid primary key default gen_random_uuid(),reference text unique not null,client_name text not null,client_phone text not null,item text not null,from_address text not null,to_address text not null,vehicle text not null,distance_km numeric default 0,amount numeric default 0,payment_method text default 'delivery',status text default 'pending',courier_id uuid,created_at timestamptz default now());
create table if not exists public.couriers(id uuid primary key default gen_random_uuid(),reference text unique not null,full_name text not null,phone text not null,vehicle text not null,status text default 'pending',created_at timestamptz default now());
alter table public.orders enable row level security; alter table public.couriers enable row level security;
drop policy if exists public_insert_orders on public.orders; create policy public_insert_orders on public.orders for insert to anon,authenticated with check(true);
drop policy if exists public_insert_couriers on public.couriers; create policy public_insert_couriers on public.couriers for insert to anon,authenticated with check(true);
drop policy if exists admin_read_orders on public.orders; create policy admin_read_orders on public.orders for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists admin_read_couriers on public.couriers; create policy admin_read_couriers on public.couriers for select to authenticated using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin'));